<section class="filmography"><div class="section-heading"><h2>A body of work.</h2><span class="eyebrow">SELECTED CREDITS</span></div><div class="catalog-grid"><?php $credits = \MSC\Presentation::filmography( $r['uuid'] ); if ( ! $credits ) { echo '<p class="empty-state">Published credits will appear here when this person is linked to a story.</p>'; } foreach ( $credits as $credit ) { echo '<div>'; \MSC\Presentation::card( $credit ); echo '<p class="credit-roles">' . esc_html( implode( ' · ', $credit['credit_roles'] ) ) . '</p></div>'; } ?></div></section>
